{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@agenticcontrolplane/opencode",
  "version": "0.5.2",
  "description": "Deterministic governance for OpenCode via the Agentic Control Plane — allow / deny / ask on every tool call, fail-open, never bricks your session. Plus zero-credential local metering: per-call tokens, cache hit rate, tool errors, per-task cost (`acp-opencode report`).",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "acp-opencode": "dist/cli.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/v2.d.ts",
      "import": "./dist/v2.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "test": "vitest run",
    "pretest:node": "npm run build",
    "test:node": "node --test test/*.node.test.mjs",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build && npm test && npm run test:node"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "governance",
    "agent",
    "policy",
    "agentic-control-plane",
    "acp"
  ],
  "license": "MIT",
  "homepage": "https://agenticcontrolplane.com",
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.4",
    "@types/node": "^24.0.0",
    "esbuild": "^0.28.1",
    "typescript": "^5.8.2",
    "vitest": "^3.2.4"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/agentic-control-plane/opencode-acp-plugin.git"
  },
  "publishConfig": {
    "access": "public"
  }
}
